const author = ({ authorid, fullName, surname, birth, death }) => {
  const surnameSuffix = ` ${surname}`
  const givenNames = fullName.endsWith(surnameSuffix)
    ? fullName.slice(0, -surnameSuffix.length)
    : fullName
  return {
    authorid,
    authorid_norm: authorid,
    full_name: fullName,
    name_for_index: `${surname}, ${givenNames}`,
    surname,
    birth: birth ? { plain: birth } : null,
    death: death ? { plain: death } : null,
    searchable: true
  }
}

