const word = (text, work, page, index) => ({
  word: text,
  attrs: { wid: `${work}-w${index}`, n: page }
})

const highlight = (work, page, index, before, match, after) => ({
  left_context: before.map((text, offset) => word(text, work, page, index * 100 + offset)),
  match: [word(match, work, page, index * 100 + 50)],
  right_context: after.map((text, offset) => word(text, work, page, index * 100 + 60 + offset))
})

